"""Local autogenerated task packages.

Subdirectories under this folder that contain an ``__init__.py`` are imported
at runtime so each package's ``gym.register`` runs. Generated trees can stay
untracked (see repo ``.gitignore``).

Generate into this directory, for example::

    python scripts/generate_task_from_dataset.py ... --output-dir src/blocksuite/tasks/autogen
"""

from __future__ import annotations

import importlib
import warnings
from pathlib import Path

_AUTOGEN_ROOT = Path(__file__).resolve().parent


def _import_autogen_task_packages() -> None:
    if not _AUTOGEN_ROOT.is_dir():
        return
    for child in sorted(_AUTOGEN_ROOT.iterdir()):
        name = child.name
        if not child.is_dir() or name.startswith("_") or name == "__pycache__":
            continue
        if not (child / "__init__.py").is_file():
            continue
        mod = f"{__name__}.{name}"
        try:
            importlib.import_module(mod)
        except Exception as exc:  # noqa: BLE001 — best-effort; one bad tree must not block others
            warnings.warn(
                f"Failed to import autogen task package {mod!r}: {exc}",
                stacklevel=1,
            )


_import_autogen_task_packages()
